      "description": "It describes the mean-field activity of a population of Hodgkin-Huxley-type neurons (Depannemaker et al 2022) linking the slow fluctuations of intra- and extra-cellular potassium ion concentrations to the mean membrane potential, and the synaptic input to the population firing rate. \nThe model is derived as the mathematical limit of an infinite number of all-to-all coupled neurons, resulting in 5 state variables:\n    :math:`x` represents a phenomenological variable connected to the firing rate, \n    :math:`V` represent the average membrane potential,\n    :math:`n` represents the gating variable for potassium K, \n    :math:`\\Delta K_{int}` represent the intracellular potassium concentration,\n    :math:`K_g` represents the extracellular potassium buffering by the external bath\n    \"\"\"",
      "references": [
        "Rabuffo2024",
        "Depannemaecker2023"
      ],
      "derived_variables": {
        "DNa_i": {
          "name": "DNa_i",
          "equation": {
            "lhs": "DNa_i",
            "rhs": "-DKi",
            "latex": false
          },
          "conditional": false
        },
        "I_Cl": {
          "name": "I_Cl",
          "equation": {
            "lhs": "I_Cl",
            "rhs": "g_Cl*(V + 26.64*log(Cl_o0/Cl_i0))",
            "latex": false
          },
          "conditional": false
        },
        "K_i": {
          "name": "K_i",
          "equation": {
            "lhs": "K_i",
            "rhs": "DKi + K_i0",
            "latex": false
          },
          "conditional": false
        },
        "beta": {
          "name": "beta",
          "equation": {
            "lhs": "beta",
            "rhs": "w_i/w_o",
            "latex": false
          },
          "conditional": false
        },
        "h": {
          "name": "h",
          "equation": {
            "lhs": "h",
            "rhs": "1.1 - 1.0/(1.0 + 24.5325301971094*exp(-8.0*n))",
            "latex": false
          },
          "conditional": false
        },
        "minf": {
          "name": "minf",
          "equation": {
            "lhs": "minf",
            "rhs": "1.0/(exp((Cmna - V)/DCmna) + 1.0)",
            "latex": false
          },
          "conditional": false
        },
        "ninf": {
          "name": "ninf",
          "equation": {
            "lhs": "ninf",
            "rhs": "1.0/(exp((Cnk - V)/DCnk) + 1.0)",
            "latex": false
          },
          "conditional": false
        },
        "r": {
          "name": "r",
          "equation": {
            "lhs": "r",
            "rhs": "R_minus*x/pi",
            "latex": false
          },
          "conditional": false
        },
        "DK_o": {
          "name": "DK_o",
          "equation": {
            "lhs": "DK_o",
            "rhs": "-DKi*beta",
            "latex": false
          },
          "conditional": false
        },
        "DNa_o": {
          "name": "DNa_o",
          "equation": {
            "lhs": "DNa_o",
            "rhs": "-DNa_i*beta",
            "latex": false
          },
          "conditional": false
        },
        "Na_i": {
          "name": "Na_i",
          "equation": {
            "lhs": "Na_i",
            "rhs": "DNa_i + Na_i0",
            "latex": false
          },
          "conditional": false
        },
        "xcond": {
          "name": "xcond",
          "symbol": "xcond",
          "equation": {
            "lhs": "xcond",
            "rhs": "Piecewise((Delta - J*r*x + 2*R_minus*x*(V - c_minus), V <= Vstar), (Delta - J*r*x + 2*R_plus*x*(V - c_plus), True))",
            "latex": false
          },
          "conditional": true,
          "cases": [
            {
              "condition": "V <= Vstar",
              "equation": {
                "lhs": "xcond",
                "rhs": "Delta - J*r*x + 2*R_minus*x*(V - c_minus)",
                "latex": false
              }
            },
            {
              "condition": "True",
              "equation": {
                "lhs": "xcond",
                "rhs": "Delta - J*r*x + 2*R_plus*x*(V - c_plus)",
                "latex": false
              }
            }
          ]
        },
        "K_o": {
          "name": "K_o",
          "equation": {
            "lhs": "K_o",
            "rhs": "DK_o + K_o0 + Kg",
            "latex": false
          },
          "conditional": false
        },
        "Na_o": {
          "name": "Na_o",
          "equation": {
            "lhs": "Na_o",
            "rhs": "DNa_o + Na_o0",
            "latex": false
          },
          "conditional": false
        },
        "I_K": {
          "name": "I_K",
          "equation": {
            "lhs": "I_K",
            "rhs": "(V - 26.64*log(K_o/K_i))*(g_K*n + g_Kl)",
            "latex": false
          },
          "conditional": false
        },
        "I_Na": {
          "name": "I_Na",
          "equation": {
            "lhs": "I_Na",
            "rhs": "(V - 26.64*log(Na_o/Na_i))*(g_Na*h*minf + g_Nal)",
            "latex": false
          },
          "conditional": false
        },
        "I_pump": {
          "name": "I_pump",
          "equation": {
            "lhs": "I_pump",
            "rhs": "1.0*rho/((exp((Ckp - K_o)/DCkp) + 1.0)*(exp((Cnap - Na_i)/DCnap) + 1.0))",
            "latex": false
          },
          "conditional": false
        },
        "V_temp": {
          "name": "V_temp",
          "equation": {
            "lhs": "V_temp",
            "rhs": "-1.0*(I_Cl + I_K + I_Na + I_pump)/Cm",
            "latex": false
          },
          "conditional": false
        },
        "Vcond": {
          "name": "Vcond",
          "symbol": "Vcond",
          "equation": {
            "lhs": "Vcond",
            "rhs": "Piecewise((R_minus*c_pop0*(-V + E)/pi - R_minus*x**2 + V_temp + eta, V <= Vstar), (R_minus*c_pop0*(-V + E)/pi - R_plus*x**2 + V_temp + eta, True))",
            "latex": false
          },
          "conditional": true,
          "cases": [
            {
              "condition": "V <= Vstar",
              "equation": {
                "lhs": "Vcond",
                "rhs": "R_minus*c_pop0*(-V + E)/pi - R_minus*x**2 + V_temp + eta",
                "latex": false
              }
            },
            {
              "condition": "True",
              "equation": {
                "lhs": "Vcond",
                "rhs": "R_minus*c_pop0*(-V + E)/pi - R_plus*x**2 + V_temp + eta",
                "latex": false
              }
            }
          ]
        }
      },
      "coupling_inputs": {
        "c_pop0": {
          "name": "c_pop0"
        }
      },
