    "derived_variables.T_V_e": {
      "name": "T_V_e",
      "equation": {
        "lhs": "T_V_e",
        "rhs": "(U_e_e**2*fe_e*tau_e**2 + U_i_e**2*fi_e*tau_i**2)/(U_e_e**2*fe_e*tau_e**2/(T_m_e + tau_e) + U_i_e**2*fi_e*tau_i**2/(T_m_e + tau_i))",
        "latex": false
      },
      "conditional": false
    },
    "derived_variables.T_V_i": {
      "name": "T_V_i",
      "equation": {
        "lhs": "T_V_i",
        "rhs": "(U_e_i**2*fe_i*tau_e**2 + U_i_i**2*fi_i*tau_i**2)/(U_e_i**2*fe_i*tau_e**2/(T_m_i + tau_e) + U_i_i**2*fi_i*tau_i**2/(T_m_i + tau_i))",
        "latex": false
      },
      "conditional": false
    },
    "derived_variables.sigma_V_e": {
      "name": "sigma_V_e",
      "equation": {
        "lhs": "sigma_V_e",
        "rhs": "sqrt(U_e_e**2*fe_e*tau_e**2/(2.0*T_m_e + 2.0*tau_e) + U_i_e**2*fi_e*tau_i**2/(2.0*T_m_e + 2.0*tau_i))",
        "latex": false
      },
      "conditional": false
    },
    "derived_variables.sigma_V_i": {
      "name": "sigma_V_i",
      "equation": {
        "lhs": "sigma_V_i",
        "rhs": "sqrt(U_e_i**2*fe_i*tau_e**2/(2.0*T_m_i + 2.0*tau_e) + U_i_i**2*fi_i*tau_i**2/(2.0*T_m_i + 2.0*tau_i))",
        "latex": false
      },
      "conditional": false
    },
    "derived_variables.S_e": {
      "name": "S_e",
      "equation": {
        "lhs": "S_e",
        "rhs": "(-sV0 + sigma_V_e)/DsV0",
        "latex": false
      },
      "conditional": false
    },
    "derived_variables.S_i": {
      "name": "S_i",
      "description": "Scaling of the remote input for the inhibitory population with\n        respect to the excitatory population.",
      "equation": {
        "lhs": "S_i",
        "rhs": "(-sV0 + sigma_V_i)/DsV0",
        "latex": false
      },
      "conditional": false
    },
